 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max({v for row in grid for v in row}, key=lambda v: sum(row.count(v) for row in grid))
    seen=set(); comps=[]
    for r in range(h):
        for c in range(w):
            if grid[r][c]==bg or (r,c) in seen: continue
            color=grid[r][c]; q=[(r,c)]; seen.add((r,c)); obj=[]
            while q:
                x,y=q.pop(); obj.append((x,y))
                for a,b in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0<=a<h and 0<=b<w and (a,b) not in seen and grid[a][b]==color:
                        seen.add((a,b)); q.append((a,b))
            comps.append(obj)
    stamp=max(comps,key=len)
    r0=min(r for r,c in stamp); r1=max(r for r,c in stamp)
    c0=min(c for r,c in stamp); c1=max(c for r,c in stamp)
    # stamp's colored cells relative to the singleton anchor (middle of bounding box)
    ar,ac=(r0+r1)//2,(c0+c1)//2
    anchors=[p for obj in comps if obj is not stamp for p in obj]
    out=[row[:] for row in grid]
    for mr,mc in anchors:
        for r,c in stamp:
            rr,cc=mr+r-ar,mc+c-ac
            if 0<=rr<h and 0<=cc<w: out[rr][cc]=grid[r][c]
    return out
